const $=s=>document.querySelector(s),uid=()=>crypto.randomUUID(),today=()=>{let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`},esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEYS=['kcal','p','f','c'],names=['Calorías','Proteínas','Grasas','Carbohidratos'],colors=['#22604a','#86a5bd','#d7ae6d','#a3b67e'];
const calories=v=>4*(+v.p||0)+4*(+v.c||0)+9*(+v.f||0);
function normalizeCalories(s){s.foods.forEach(f=>f.kcal=calories(f));s.goals.forEach(g=>g.kcal=calories(g));Object.values(s.days).forEach(d=>{if(d.goal)d.goal.kcal=calories(d.goal);d.entries.forEach(e=>e.items.forEach(x=>x.kcal=calories(x)))});return s}
const seeds=[['Huevo entero','1 pieza grande · 50 g',72,6.3,4.8,.4,'🥚'],['Leche entera','100 ml',61,3.2,3.3,4.8,'🥛'],['Pechuga de pollo cocida','100 g · sin piel',165,31,3.6,0,'🍗'],['Pan integral','1 rebanada · 28 g',69,3.6,1.1,11.6,'🍞'],['Plátano','1 mediano · 118 g',105,1.3,.4,27,'🍌'],['Proteína en polvo','1 scoop · 30 g',120,24,2,3,'🥤'],['Avena seca','100 g',389,16.9,6.9,66.3,'🥣'],['Arroz blanco cocido','100 g',130,2.7,.3,28.2,'🍚'],['Tortilla de maíz','1 pieza · 25 g',52,1.4,.7,10.7,'🫓'],['Aguacate','100 g · pulpa',160,2,14.7,8.5,'🥑'],['Atún en agua','100 g · escurrido',116,25.5,.8,0,'🐟'],['Yogur griego natural','100 g · sin grasa',59,10.3,.4,3.6,'🥣'],['Manzana','1 mediana · 182 g',95,.5,.3,25.1,'🍎'],['Frijoles cocidos','100 g · sin aceite',127,8.7,.5,22.8,'🫘'],['Almendras','30 g',174,6.4,15,6.5,'🌰'],['Aceite de oliva','1 cucharada · 14 g',119,0,13.5,0,'🫒'],['Papa cocida','100 g',87,1.9,.1,20.1,'🥔'],['Brócoli cocido','100 g',35,2.4,.4,7.2,'🥦'],['Salmón cocido','100 g',206,22.1,12.4,0,'🐟'],['Queso panela','100 g',260,20,20,2,'🧀']];
function initial(){let foods=seeds.map((r,i)=>({id:'food'+i,name:r[0],unit:r[1],kcal:r[2],p:r[3],f:r[4],c:r[5],icon:r[6]}));return {version:1,foods,recipes:[{id:'recipe1',name:'Huevos con pan',type:'Platillo',items:[{foodId:'food0',q:2},{foodId:'food3',q:1}]},{id:'recipe2',name:'Mi desayuno habitual',type:'Comida',items:[{foodId:'food0',q:2},{foodId:'food3',q:1},{foodId:'food4',q:1},{foodId:'food1',q:2.5},{foodId:'food5',q:1}]}],days:{},metrics:[],goals:[]}}
let state;try{state=JSON.parse(localStorage.getItem('fitme-v1'))||initial()}catch{state=initial()}normalizeCalories(state);let tab=0,date=today();$('#date').value=date;$('#date').onchange=e=>{date=e.target.value||today();render()};
function save(){try{localStorage.setItem('fitme-v1',JSON.stringify(state));return true}catch{alert('No se pudo guardar. Exporta un respaldo; el almacenamiento puede estar lleno.');return false}}function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',2800)}
const sum=items=>items.reduce((a,x)=>{KEYS.forEach(k=>a[k]+=(k==='kcal'?calories(x):(+x[k]||0))*x.q);return a},{kcal:0,p:0,f:0,c:0}),entries=(d=date)=>state.days[d]?.entries||[],total=(d=date)=>sum(entries(d).flatMap(e=>e.items)),goal=(d=date)=>state.days[d]?.goal||[...state.goals].sort((a,b)=>b.date.localeCompare(a.date)).find(g=>g.date<=d),fmt=n=>Math.round(n*10)/10,nut=v=>`${Math.round(calories(v))} kcal · P ${fmt(v.p)} g · G ${fmt(v.f)} g · C ${fmt(v.c)} g`;
function day(){if(!state.days[date])state.days[date]={entries:[],goal:goal()?{...goal()}:null};return state.days[date]}function modal(html){$('#modal-content').innerHTML=`<button class="ghost close" onclick="$('#modal').close()" aria-label="Cerrar">✕</button>${html}`;$('#modal').showModal()}function go(n){tab=n;render()}
function render(){let expanded = Array.from(document.querySelectorAll ? document.querySelectorAll("details[open][data-entry]") : []).map(x=>x.dataset.entry);let labels=['Resumen','Mi día','Biblioteca','Registro'];$('#nav').innerHTML=labels.map((v,i)=>`<button class="${tab===i?'active':''}" onclick="go(${i})"><b>${['◫','◷','▤','☷'][i]}</b>${v}</button>`).join('');$('#title').textContent=['Tu día, en equilibrio','Cada comida cuenta','Tus favoritos, a mano','Tu progreso empieza aquí'][tab];$('#content').innerHTML=[overview,diary,library,settings][tab]();if(tab===2)filterFoods();if(tab===1)expanded.forEach(id=>{let el=document.querySelector(`[data-entry="${id}"]`);if(el)el.open=true});}
function overview(){let t=total(),g=goal();return `<div class="hero"><div><h2>Pequeños hábitos. Grandes cambios.</h2><p class="sub">${entries().length?'Así va tu nutrición de hoy. Sigue a tu ritmo.':'Un nuevo día para cuidarte. Registra tu primera comida.'}</p></div><span class="symbol">✳</span></div><div class="section-head"><h2>Tu balance diario</h2><button onclick="picker()">＋ Agregar comida</button></div>${!g?'<div class="notice">Define tus objetivos para ver tu progreso diario. <a href="#" onclick="go(3);return false">Configurar objetivos →</a></div>':''}<div class="grid">${KEYS.map((k,i)=>`<div class="card macro" style="--color:${colors[i]}"><div class="label">${names[i]}<span style="color:${colors[i]}">${['◉','◈','◐','✳'][i]}</span></div><strong>${Math.round(t[k])}<span class="goal-denominator">/${g?fmt(g[k]):'—'}</span></strong> <small>${i?'g':'kcal'}</small><div class="bar"><i style="width:${g?Math.min(100,t[k]/g[k]*100):0}%"></i></div><small>${g?`de ${fmt(g[k])} ${i?'g':'kcal'} <span style="float:right">${Math.round(t[k]/g[k]*100)}%</span>`:'Sin objetivo definido'}</small></div>`).join('')}</div><div class="section-head"><h2>Más que un número</h2><button class="ghost" onclick="metricForm()">Registrar métricas ↗</button></div><div class="grid">${[['weight','Peso','kg'],['fat','Grasa corporal','%'],['muscle','Músculo','%'],['visceral','Grasa visceral','nivel']].map(([key,label,unit])=>{let ms=state.metrics.filter(m=>m.date<=date&&m[key]!=null).sort((a,b)=>a.date.localeCompare(b.date)),last=ms.at(-1);return `<div class="card metric"><p>${label}</p><strong>${last?fmt(last[key]):'—'}</strong> <span class="sub">${unit}</span>${spark(ms,key)}<p>${last?'Último registro: '+last.date:'Tu primer registro está por venir'}</p></div>`}).join('')}</div><div class="two"><div class="card"><div class="section-head" style="margin:0"><h2>Tu constancia</h2><span class="sub">${new Date(date+'T12:00:00').toLocaleDateString('es-MX',{month:'long',year:'numeric'})}</span></div>${calendar()}<div class="legend"><span><i class="dot"></i>Dentro del objetivo</span><span><i class="dot red"></i>Excedido</span><span><i class="dot gray"></i>Sin evaluar</span></div><p class="sub" style="font-size:11px">Se marca rojo si superas cualquiera de tus cuatro objetivos. Quedar por debajo cuenta como verde.</p></div><div class="card"><div class="section-head" style="margin:0"><h2>En tu plato</h2><button class="ghost" onclick="go(1)">Ver día →</button></div>${entries().length?entries().slice(0,3).map(e=>`<div class="row"><div class="food-icon">${e.icon||'🍽️'}</div><div class="info"><b>${esc(e.name)}</b><div class="nutrition">${nut(sum(e.items))}</div></div></div>`).join(''):'<div class="empty"><div class="big">♧</div><h3>Tu diario está listo</h3><p>Agrega un alimento o tu desayuno habitual.<br>Nosotros hacemos las cuentas.</p><button class="secondary" onclick="picker()">Registrar mi primera comida</button></div>'}</div></div>`}
function spark(ms,k){if(ms.length<2)return '<svg class="spark" viewBox="0 0 200 48"><path d="M0 35 H200" stroke="#e3e9db" stroke-dasharray="4 5"/></svg>';let a=ms.slice(-20),lo=Math.min(...a.map(x=>x[k])),hi=Math.max(...a.map(x=>x[k])),pts=a.map((x,i)=>`${i*200/(a.length-1)},${40-(x[k]-lo)/(hi-lo||1)*32}`).join(' ');return `<svg class="spark" viewBox="0 0 200 48" role="img" aria-label="Evolución de ${k}"><polyline points="${pts}" fill="none" stroke="#8ca974" stroke-width="2.5"/></svg>`}
function calendar(){let d=new Date(date+'T12:00:00'),y=d.getFullYear(),m=d.getMonth(),start=(new Date(y,m,1).getDay()+6)%7,n=new Date(y,m+1,0).getDate();return `<div class="calendar">${['L','M','M','J','V','S','D'].map(x=>`<span>${x}</span>`).join('')}${'<span></span>'.repeat(start)}${Array.from({length:n},(_,i)=>{let key=`${y}-${String(m+1).padStart(2,'0')}-${String(i+1).padStart(2,'0')}`,g=goal(key),t=total(key),cl=entries(key).length&&g?(KEYS.some(k=>t[k]>g[k])?'bad':'good'):'';return `<button class="day ${cl} ${key===date?'selected':''}" onclick="selectDate('${key}')">${i+1}</button>`}).join('')}</div>`}function selectDate(d){date=d;$('#date').value=d;render()}
function diary(){let t=total();return `<div class="summary-strip">${KEYS.map((k,i)=>`<div><span>${names[i]}</span><strong>${Math.round(t[k])} <small>${i?'g':'kcal'}</small></strong></div>`).join('')}</div><div class="section-head"><h2>Lo que has comido</h2><button onclick="picker()">＋ Agregar</button></div>${entries().length?entries().map(e=>`<details data-entry="${e.id}" class="card" ${e.items.length===1?'open':''}><summary><div><h3>${esc(e.name)}</h3><div class="nutrition">${nut(sum(e.items))} · ${e.items.length} alimento${e.items.length===1?'':'s'}</div></div></summary><div>${e.items.map((x,i)=>`<div class="row"><div class="info"><b>${esc(x.name)}</b><div class="nutrition">${esc(x.unit)}<br>${nut(sum([x]))}</div></div><div class="stepper"><button aria-label="Restar ${esc(x.name)}" onclick="adjust('${e.id}',${i},-1)">−</button><input class="quantity" type="number" min="0.01" max="10000" step="any" aria-label="Porciones de ${esc(x.name)}" value="${x.q}" onchange="quantity('${e.id}',${i},this.value)"><button aria-label="Sumar ${esc(x.name)}" onclick="adjust('${e.id}',${i},1)">+</button></div><button class="ghost" aria-label="Quitar ${esc(x.name)}" onclick="removeItem('${e.id}',${i})">×</button></div>`).join('')}</div><div class="actions"><button class="ghost" onclick="removeEntry('${e.id}')">Eliminar registro</button><button class="secondary" onclick="picker('${e.id}')">＋ Ingrediente extra</button></div></details>`).join(''):'<div class="card empty"><div class="big">◷</div><h3>Todo empieza con un bocado</h3><p>Elige un alimento, un platillo o una comida guardada.</p><button onclick="picker()">Agregar comida</button></div>'}`}
function adjust(id,i,delta){let e=entries().find(e=>e.id===id);quantity(id,i,Math.max(.25,+(e.items[i].q+delta).toFixed(2)))}function quantity(id,i,v){v=+v;if(!Number.isFinite(v)||v<=0||v>10000){toast('Usa una cantidad mayor que 0');render();return}entries().find(e=>e.id===id).items[i].q=v;save();render()}function removeItem(id,i){let e=entries().find(e=>e.id===id);e.items.splice(i,1);if(!e.items.length)day().entries=entries().filter(e=>e.id!==id);save();render()}function removeEntry(id){if(confirm('¿Eliminar esta comida del día?')){day().entries=entries().filter(e=>e.id!==id);save();render()}}
function recipeItems(r){return r.items.map(x=>({...state.foods.find(f=>f.id===x.foodId),q:x.q})).filter(x=>x.id)}let pickTarget='';function picker(target=''){pickTarget=target;modal(`<h2>¿Qué vas a comer?</h2><p class="sub">Se agregará al ${date}. Las porciones se pueden ajustar después.</p><input class="search" placeholder="Buscar en tus alimentos y recetas…" oninput="pickerList(this.value)"><div id="pick-list" class="list"></div>`);pickerList('')}
function pickerList(query){let q=query.toLowerCase();$('#pick-list').innerHTML=[...state.recipes.map(r=>({...r,recipe:true})),...state.foods].filter(f=>f.name.toLowerCase().includes(q)).map(f=>`<div class="row"><div class="food-icon">${f.icon||'🍽️'}</div><div class="info"><b>${esc(f.name)}</b><div class="nutrition">${f.recipe?esc(f.type):esc(f.unit)}<br>${nut(f.recipe?sum(recipeItems(f)):f)}</div></div><button class="secondary" onclick="addFood('${f.id}',${!!f.recipe})" aria-label="Agregar ${esc(f.name)}">＋</button></div>`).join('')||'<div class="empty">No encontramos ese alimento. Créalo en Biblioteca.</div>'}
function addFood(id,isRecipe){let f=(isRecipe?state.recipes:state.foods).find(f=>f.id===id),items=isRecipe?recipeItems(f):[{...f,q:1}];if(pickTarget){entries().find(e=>e.id===pickTarget).items.push(...structuredClone(items))}else{day().entries.push({id:uid(),name:f.name,icon:f.icon,items:structuredClone(items)})}save();$('#modal').close();render();toast('Agregado a tu día')}
let libMode='foods';function library(){return `<div class="section-head"><div class="chips"><button class="${libMode==='foods'?'':'secondary'}" onclick="libMode='foods';render()">Alimentos</button><button class="${libMode==='recipes'?'':'secondary'}" onclick="libMode='recipes';render()">Platillos y comidas</button></div><button onclick="${libMode==='foods'?'foodForm()':'recipeForm()'}">＋ Crear</button></div><input id="food-search" class="search" placeholder="Buscar en mi biblioteca…" oninput="filterFoods()"><div id="food-list" class="card list"></div>`}
function filterFoods(){let q=$('#food-search').value.toLowerCase(),arr=libMode==='foods'?state.foods:state.recipes;$('#food-list').innerHTML=arr.filter(f=>f.name.toLowerCase().includes(q)).map(f=>`<div class="row"><div class="food-icon">${f.icon||'🍽️'}</div><div class="info"><b>${esc(f.name)}</b><div class="nutrition">${esc(f.unit||f.type)} · ${nut(f.unit?f:sum(recipeItems(f)))}</div></div><button class="ghost" onclick="${f.unit?'foodForm':'recipeForm'}('${f.id}')">Editar</button><button class="secondary" onclick="addFood('${f.id}',${!f.unit})">＋</button></div>`).join('')||'<div class="empty">No hay resultados.</div>';pickTarget=''}
function field(label,name,value='',type='number',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" max="100000" step="any"':''} ${extra}></label>`}
function foodForm(id){let f=state.foods.find(x=>x.id===id)||{};modal(`<h2>${id?'Editar':'Nuevo'} alimento</h2><form oninput="updateCalories(this)" onsubmit="saveFood(event,'${id||''}')"><div class="form-grid">${field('Nombre','name',f.name||'','text','required maxlength="90"')}${field('Porción base (ej. 100 g o 1 pieza)','unit',f.unit||'','text','required maxlength="80"')}${macroFields(f)}</div><p class="sub">Las cantidades del diario multiplican esta porción. Los cambios no alteran comidas ya registradas.</p><div class="actions">${id?`<button type="button" class="ghost" onclick="deleteFood('${id}')">Eliminar</button>`:''}<button>Guardar alimento</button></div></form>`)}
function saveFood(ev,id){ev.preventDefault();let d=Object.fromEntries(new FormData(ev.target));KEYS.forEach(k=>d[k]=+d[k]);d.kcal=calories(d);d.name=d.name.trim();d.unit=d.unit.trim();if(!d.name||!d.unit)return;let old=state.foods.find(f=>f.id===id);if(old)Object.assign(old,d);else state.foods.push({...d,id:uid(),icon:'🥗'});save();$('#modal').close();render();toast('Alimento guardado')}function deleteFood(id){if(state.recipes.some(r=>r.items.some(x=>x.foodId===id))){toast('Primero quita este alimento de tus recetas');return}if(confirm('¿Eliminar este alimento de la biblioteca?')){state.foods=state.foods.filter(f=>f.id!==id);save();$('#modal').close();render()}}
let draft=[];function recipeForm(id){let r=state.recipes.find(r=>r.id===id)||{};draft=structuredClone(r.items||[]);modal(`<h2>${id?'Editar':'Nueva'} receta</h2><form onsubmit="saveRecipe(event,'${id||''}')"><div class="form-grid">${field('Nombre','name',r.name||'','text','required maxlength="90"')}<label>Tipo<select name="type"><option ${r.type==='Platillo'?'selected':''}>Platillo</option><option ${r.type==='Comida'?'selected':''}>Comida</option></select></label></div><div class="section-head"><h3>Ingredientes y porciones</h3></div><select id="ingredient" style="width:100%"><optgroup label="Alimentos">${state.foods.map(f=>`<option value="${f.id}">${esc(f.name)} · ${esc(f.unit)}</option>`).join('')}</optgroup><optgroup label="Añadir receta completa">${state.recipes.filter(x=>x.id!==id).map(x=>`<option value="r:${x.id}">${esc(x.name)}</option>`).join('')}</optgroup></select><button type="button" class="secondary" style="margin-top:10px" onclick="draftAdd()">＋ Agregar ingrediente</button><div id="draft" class="list"></div><div class="actions">${id?`<button type="button" class="ghost" onclick="deleteRecipe('${id}')">Eliminar</button>`:''}<button>Guardar receta</button></div></form>`);renderDraft()}
function draftAdd(){let id=$('#ingredient').value;if(!id)return;let add=id.startsWith('r:')?state.recipes.find(r=>r.id===id.slice(2)).items:[{foodId:id,q:1}];add.forEach(x=>{let old=draft.find(d=>d.foodId===x.foodId);if(old)old.q+=x.q;else draft.push({...x})});renderDraft()}function renderDraft(){$('#draft').innerHTML=draft.map((x,i)=>{let f=state.foods.find(f=>f.id===x.foodId);return `<div class="row"><div class="info"><b>${esc(f.name)}</b><div class="nutrition">${esc(f.unit)}</div></div><input class="quantity" aria-label="Porciones de ${esc(f.name)}" type="number" min="0.01" max="10000" step="any" value="${x.q}" required onchange="draft[${i}].q=+this.value"><button type="button" class="ghost" onclick="draft.splice(${i},1);renderDraft()">×</button></div>`}).join('')||'<p class="sub">Agrega alimentos o una receta guardada.</p>'}
function saveRecipe(ev,id){ev.preventDefault();if(!draft.length||draft.some(x=>!Number.isFinite(x.q)||x.q<=0)){toast('Agrega ingredientes con cantidades válidas');return}let d=Object.fromEntries(new FormData(ev.target));d.name=d.name.trim();if(!d.name)return;let old=state.recipes.find(r=>r.id===id);if(old)Object.assign(old,d,{items:structuredClone(draft)});else state.recipes.push({...d,id:uid(),items:structuredClone(draft)});save();$('#modal').close();render();toast('Receta guardada')}function deleteRecipe(id){if(confirm('¿Eliminar la receta guardada?')){state.recipes=state.recipes.filter(r=>r.id!==id);save();$('#modal').close();render()}}
const metricFields=[['weight','Peso (kg)'],['fat','Grasa corporal (%)'],['muscle','Músculo (%)'],['visceral','Grasa visceral (nivel)'],['waist','Cintura (cm)'],['bmi','IMC']];
function settings(){let g=goal()||{};return `<div class="two" style="margin-top:0"><div class="card"><h2>Tus objetivos diarios</h2><div class="actions" style="justify-content:flex-start;margin:16px 0"><button class="secondary" onclick="calculatorForm()">✳ Calcular mis macros</button></div><form id="goals-form" oninput="updateCalories(this)" onsubmit="saveGoals(event)"><div class="form-grid">${field('Vigentes desde','date',date,'date','required')}${macroFields(g)}</div><div class="actions"><button>Guardar objetivos</button></div></form></div><div class="card"><h2>Tu cuerpo, con perspectiva</h2><p class="sub">Registra las métricas que tengas disponibles. Cada registro construye tu historia.</p><button onclick="metricForm()">＋ Registrar medición</button><h3>Tus datos se quedan contigo</h3><p class="sub">Se guardan en este navegador, sin sincronización. Exporta un respaldo antes de cambiar de dispositivo o borrar sus datos.</p><div class="chips"><button class="secondary" onclick="exportData()">Exportar respaldo</button><button class="secondary" onclick="$('#import').click()">Importar respaldo</button><input id="import" hidden type="file" accept="application/json,.json" onchange="importData(this.files[0])"></div></div></div><div class="section-head"><h2>Histórico de mediciones</h2></div><div class="card table-wrap">${state.metrics.length?`<table><thead><tr><th>Fecha</th>${metricFields.map(x=>`<th>${x[1]}</th>`).join('')}<th></th></tr></thead><tbody>${[...state.metrics].sort((a,b)=>b.date.localeCompare(a.date)).map(m=>`<tr><td>${m.date}</td>${metricFields.map(([k])=>`<td>${m[k]??'—'}</td>`).join('')}<td><button class="ghost" onclick="metricForm('${m.id}')">Editar</button></td></tr>`).join('')}</tbody></table>`:'<div class="empty">Aún no hay mediciones. Tu punto de partida puede ser hoy.</div>'}</div>`}
function saveGoals(ev){ev.preventDefault();let g=Object.fromEntries(new FormData(ev.target));KEYS.forEach(k=>g[k]=+g[k]);g.kcal=calories(g);if(KEYS.some(k=>!Number.isFinite(g[k])||g[k]<=0)){toast('Los objetivos deben ser mayores que cero');return}state.goals=state.goals.filter(x=>x.date!==g.date);state.goals.push(g);Object.entries(state.days).forEach(([d,v])=>{if((!v.goal&&d>=g.date)||d===g.date)v.goal={...g}});save();render();toast('Objetivos guardados')}
function metricForm(id){let m=state.metrics.find(x=>x.id===id)||{date};modal(`<h2>${id?'Editar':'Registrar'} medición</h2><form onsubmit="saveMetric(event,'${id||''}')"><div class="form-grid">${field('Fecha','date',m.date,'date','required')}${metricFields.map(([k,n])=>field(n,k,m[k]??'')).join('')}</div><p class="sub">Puedes dejar vacías las métricas que no conozcas.</p><div class="actions">${id?`<button type="button" class="ghost" onclick="deleteMetric('${id}')">Eliminar</button>`:''}<button>Guardar medición</button></div></form>`)}
function saveMetric(ev,id){ev.preventDefault();let d=Object.fromEntries(new FormData(ev.target));metricFields.forEach(([k])=>d[k]=d[k]===''?null:+d[k]);if(metricFields.every(([k])=>d[k]==null)){toast('Captura al menos una métrica');return}if(['fat','muscle'].some(k=>d[k]>100)){toast('Los porcentajes no pueden superar 100');return}let duplicate=state.metrics.find(m=>m.date===d.date&&m.id!==id);if(duplicate){toast('Ya existe una medición para esa fecha. Edítala en el histórico.');return}let old=state.metrics.find(x=>x.id===id);if(old)Object.assign(old,d);else state.metrics.push({...d,id:uid()});save();$('#modal').close();render();toast('Medición guardada')}function deleteMetric(id){if(confirm('¿Eliminar esta medición?')){state.metrics=state.metrics.filter(m=>m.id!==id);save();$('#modal').close();render()}}
function exportData(){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.href=url;a.download=`fit-me-respaldo-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function validBackup(s){const num=v=>typeof v==='number'&&Number.isFinite(v)&&v>=0,dt=v=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v),food=f=>f&&typeof f.id==='string'&&typeof f.name==='string'&&typeof f.unit==='string'&&KEYS.every(k=>num(f[k])),g=v=>v&&dt(v.date)&&KEYS.every(k=>num(v[k])&&v[k]>0);if(!s||s.version!==1||!Array.isArray(s.foods)||!s.foods.every(food)||!Array.isArray(s.recipes)||!Array.isArray(s.metrics)||!Array.isArray(s.goals)||!s.goals.every(g)||!s.days||typeof s.days!=='object'||Array.isArray(s.days))return false;let ids=new Set(s.foods.map(f=>f.id));return s.recipes.every(r=>typeof r.id==='string'&&typeof r.name==='string'&&['Platillo','Comida'].includes(r.type)&&Array.isArray(r.items)&&r.items.length&&r.items.every(x=>ids.has(x.foodId)&&num(x.q)&&x.q>0))&&s.metrics.every(m=>typeof m.id==='string'&&dt(m.date)&&metricFields.every(([k])=>m[k]==null||num(m[k])))&&Object.entries(s.days).every(([d,v])=>dt(d)&&v&&(!v.goal||g(v.goal))&&Array.isArray(v.entries)&&v.entries.every(e=>typeof e.id==='string'&&typeof e.name==='string'&&Array.isArray(e.items)&&e.items.every(x=>food(x)&&num(x.q)&&x.q>0)))}
async function importData(file){if(!file)return;try{if(file.size>10000000)throw Error();let s=JSON.parse(await file.text());if(!validBackup(s))throw Error();if(confirm('El respaldo reemplazará los datos actuales. ¿Continuar?')){state=normalizeCalories(s);save();render();toast('Respaldo importado')}}catch{toast('El archivo no es un respaldo válido de Fit me')}}
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))$('#modal').close()});render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
